import { defineConfig } from "drizzle-kit";
import fs from "fs";
import path from "path";

// Automatically resolves the local Miniflare D1 SQLite file generated by Wrangler
function getLocalD1DatabasePath(): string | null {
  const d1Dir = path.resolve(
    process.cwd(),
    ".wrangler/state/v3/d1/miniflare-D1DatabaseObject",
  );
  if (!fs.existsSync(d1Dir)) return null;
  const files = fs.readdirSync(d1Dir);
  const sqliteFile = files.find(
    (file) => file.endsWith(".sqlite") && file !== "metadata.sqlite",
  );
  return sqliteFile ? path.join(d1Dir, sqliteFile) : null;
}

const localDbPath = getLocalD1DatabasePath();

export default defineConfig({
  dialect: "sqlite",
  schema: "./src/db/schema/index.ts",
  out: "./drizzle",
  ...(process.env.CLOUDFLARE_ACCOUNT_ID && process.env.CLOUDFLARE_D1_TOKEN
    ? {
        driver: "d1-http",
        dbCredentials: {
          accountId: process.env.CLOUDFLARE_ACCOUNT_ID,
          databaseId:
            process.env.CLOUDFLARE_DATABASE_ID ??
            "b0b805f8-5d90-4cf8-a3d3-5b482a652578",
          token: process.env.CLOUDFLARE_D1_TOKEN,
        },
      }
    : localDbPath
      ? {
          dbCredentials: {
            url: `file:${localDbPath}`,
          },
        }
      : {}),
});
